const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define southern Brazilian Amazon region
  const southernAmazon = ee.Geometry.Rectangle([-75, -15, -45, -5]);

  // 2. Load VIIRS active fire data
  const viirs2019 = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGML')
    .filterDate('2019-01-01', '2019-12-31')
    .filterBounds(southernAmazon);

  const viirs2020 = ee.ImageCollection('NOAA/VIIRS/001/VNP14IMGML')
    .filterDate('2020-01-01', '2020-12-31')
    .filterBounds(southernAmazon);

  // 3. Check collection sizes
  const size2019 = viirs2019.size().getInfo();
  const size2020 = viirs2020.size().getInfo();

  console.log(`2019 Images: ${size2019}`);
  console.log(`2020 Images: ${size2020}`);

  if (size2019 === 0 && size2020 === 0) {
    console.log('No VIIRS data found for either year.');
    console.log('<answer>C1</answer>');
    return;
  }

  if (size2019 === 0 || size2020 === 0) {
    console.log('Missing data for one year.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Count fire detections (each detection is a feature)
  const count2019 = viirs2019.filterBounds(southernAmazon).size().getInfo();
  const count2020 = viirs2020.filterBounds(southernAmazon).size().getInfo();

  // 5. For more accurate counts, sum all fire pixels across all images
  const fireCount2019 = viirs2019.map(function(img) {
    return img.select('Bright_ti4').unmask(0);
  }).sum().reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: southernAmazon,
    scale: 1000,
    maxPixels: 1e9
  }).get('Bright_ti4');

  const fireCount2020 = viirs2020.map(function(img) {
    return img.select('Bright_ti4').unmask(0);
  }).sum().reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: southernAmazon,
    scale: 1000,
    maxPixels: 1e9
  }).get('Bright_ti4');

  const fires2019 = fireCount2019.getInfo();
  const fires2020 = fireCount2020.getInfo();

  console.log(`2019 Fire Pixels: ${fires2019}`);
  console.log(`2020 Fire Pixels: ${fires2020}`);

  // 6. Validation
  if (fires2019 === null || fires2020 === null) {
    console.log('Calculation failed.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (fires2019 === 0 && fires2020 === 0) {
    console.log('No fire pixels detected in either year.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 7. Final answer
  console.log(`Comparison: 2020 (${fires2020}) vs 2019 (${fires2019})`);

  if (fires2020 > fires2019) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
